      "status": "trial",
      "ageBasis": "editorial-context",
      "ageNote": "這篇以青少年談自身診斷的情境編入 13–17 歲。訪談者當時 16–18 歲，回顧自己過去的經驗。目錄年齡是閱讀情境，告知時機仍要看孩子的問題與溝通方式。",
